cat << 'EOF' > /tmp/test_sample_envelope.R
sample_candidate <- function(x, h, h_prime, z, I) {
  k <- length(x)
  I_tot <- sum(I)
  p <- I / I_tot
  cum_p <- c(0, cumsum(p))

  u_rand <- runif(1)
  j <- findInterval(u_rand, cum_p, rightmost.closed = TRUE)
  if (j < 1) j <- 1
  if (j > k) j <- k

  u_prime <- (u_rand - cum_p[j]) / p[j]
  u_prime <- min(max(u_prime, 1e-15), 1 - 1e-15)

  b <- h_prime[j]
  z_lower <- z[j]
  z_upper <- z[j + 1]

  if (abs(b) < 1e-10) {
    x_cand <- z_lower + u_prime * (z_upper - z_lower)
  } else if (is.infinite(z_upper)) {
    x_cand <- z_lower + log(1 - u_prime) / b
  } else if (is.infinite(z_lower)) {
    x_cand <- z_upper + log(u_prime) / b
  } else {
    delta <- z_upper - z_lower
    b_delta <- b * delta
    if (b > 0) {
      x_cand <- z_lower + log1p(u_prime * expm1(b_delta)) / b
    } else {
      x_cand <- z_upper + log1p((1 - u_prime) * expm1(-b_delta)) / b
    }
  }
  return(list(x_cand = x_cand, j = j))
}

x <- c(-1, 0, 1)
h <- log(dnorm(x))
h_p <- -x
z <- c(-Inf, -0.5, 0.5, Inf)
I <- c(0.3989423, 0.3989423, 0.3989423)

samples <- replicate(10000, sample_candidate(x, h, h_p, z, I)$x_cand)
cat("Mean:", mean(samples), "SD:", sd(samples), "\n")
