    non_lc <- function(x) exp(x^3)
    err_caught <- FALSE
    tryCatch({
      ars(non_lc, 100, lb = 0, ub = 2, x = c(0.5, 1.0, 1.5))
    }, error = function(e) {
      err_caught <<- TRUE
    })

    if (err_caught) {
      cat("TEST_NON_LOG_CONCAVE: PASS | Correctly detected non-log-concave density and raised error\n")
    } else {
      cat("TEST_NON_LOG_CONCAVE: FAIL | Did not raise error on non-log-concave density\n")
      all_passed <- FALSE
    }
  }, error = function(e) {
    cat(sprintf("TEST_NON_LOG_CONCAVE: FAIL | Unexpected error: %s\n", e$message))
    all_passed <<- FALSE
  })

  cat("\nRunning Test: Invalid Inputs Validation...\n")
  tryCatch({
    invalid_n_caught <- FALSE
    invalid_domain_caught <- FALSE

    tryCatch(ars(dnorm, n = -5), error = function(e) invalid_n_caught <<- TRUE)
    tryCatch(ars(dnorm, n = 100, lb = 5, ub = 2), error = function(e) invalid_domain_caught <<- TRUE)

    if (invalid_n_caught && invalid_domain_caught) {
      cat("TEST_INVALID_INPUTS: PASS | Correctly caught invalid sample count and domain boundaries\n")
    } else {
      cat("TEST_INVALID_INPUTS: FAIL | Failed to catch invalid inputs\n")
      all_passed <- FALSE
    }
  }, error = function(e) {
    cat(sprintf("TEST_INVALID_INPUTS: FAIL | Unexpected error: %s\n", e$message))
    all_passed <<- FALSE
  })

  cat("\n=========================================\n")
  if (all_passed) {
    cat("  ALL TESTS PASSED SUCCESSFULLY!\n")
  } else {
    cat("  SOME TESTS FAILED!\n")
  }
  cat("=========================================\n")
}

if (!interactive()) {
  test()
}
